{"sql": "ALTER TABLE core_record ADD COLUMN prime_flag BOOLEAN;
UPDATE core_record
SET prime_flag = CASE WHEN EXISTS (
  SELECT 1
  FROM credit_and_compliance cc
  JOIN bank_and_transactions b  ON b.bankexpref  = cc.compbankref
  JOIN expenses_and_assets x    ON x.expemplref  = b.bankexpref
  JOIN employment_and_income e  ON e.emplcoreref = x.expemplref
  WHERE e.emplcoreref = core_record.coreregistry
    AND cc.credscore > 720
    AND cc.defhist IN ('Excellent','Good')
    AND cc.risklev = 'Low'
) THEN TRUE ELSE FALSE END;
SELECT prime_flag, COUNT(*) AS cnt FROM core_record GROUP BY prime_flag;
SELECT coreregistry, prime_flag FROM core_record LIMIT 5;"}

