{"sql": "UPDATE compliancecase
SET risksc = (
  SELECT MIN(100.0, (
    0.2 * (json_extract(t.risk_indicators,'$.spoofprob') / 100.0)
  + 0.2 * (json_extract(t.risk_indicators,'$.frontscore') / 100.0)
  + 0.2 * ((json_extract(t.risk_indicators,'$.qstuffindex') - (SELECT MIN(json_extract(risk_indicators,'$.qstuffindex')) FROM transactionrecord)) / ((SELECT MAX(json_extract(risk_indicators,'$.qstuffindex')) FROM transactionrecord) - (SELECT MIN(json_extract(risk_indicators,'$.qstuffindex')) FROM transactionrecord)))
  + 0.2 * CASE json_extract(t.risk_indicators,'$.washsus') WHEN 'Low' THEN 0.1 WHEN 'Medium' THEN 0.5 WHEN 'High' THEN 1.0 END
  + 0.2 * CASE json_extract(t.risk_indicators,'$.layerind') WHEN 'None' THEN 0.0 WHEN 'Suspected' THEN 0.5 WHEN 'Confirmed' THEN 1.0 END
  ) * 100.0
  ))
  FROM transactionrecord t
  WHERE compliancecase.transref = t.transreg
    AND t.transtime >= '2024-01-01';
SELECT COUNT(*) AS updated, MIN(risksc) AS mn, MAX(risksc) AS mx FROM compliancecase;
SELECT compreg, risksc FROM compliancecase WHERE risksc > 100 LIMIT 5;
SELECT c.compreg, c.risksc FROM compliancecase c JOIN transactionrecord t ON c.transref = t.transreg WHERE t.transtime < '2024-01-01' LIMIT 5;"}

{"sql": "CREATE TRIGGER IF NOT EXISTS prevent_premature_resolution_trigger
BEFORE UPDATE OF resstat ON enforcementactions
WHEN NEW.resstat = 'Resolved'
 AND OLD.resstat IS NOT 'Resolved'
 AND (SELECT (0.6 * id.behansc + 0.4 * id.netansc)
      FROM investigationdetails id
      JOIN compliancecase cc ON id.compref = cc.compreg
      WHERE id.invdetreg = NEW.invdetref) > 75.0
BEGIN
  SELECT RAISE(ABORT, 'Premature Resolution Block: Investigation Intensity Index exceeds 75.0; this high-risk enforcement action requires further review before resolution.');
END;

-- Verify: update a non-Resolved row whose III > 75 (should abort)
UPDATE enforcementactions SET resstat = 'Resolved' WHERE enforcereg = 'ENF_R2LMP';

-- Verify: update a non-Resolved row whose III <= 75 (should succeed)
UPDATE enforcementactions SET resstat = 'Resolved' WHERE enforcereg = (SELECT ea.enforcereg FROM enforcementactions ea JOIN investigationdetails id ON ea.invdetref = id.invdetreg WHERE ea.resstat <> 'Resolved' AND 0.6*id.behansc + 0.4*id.netansc <= 75.0 LIMIT 1);

SELECT 'trigger exists' AS check, name FROM sqlite_master WHERE type = 'trigger' AND name = 'prevent_premature_resolution_trigger';"}

{"sql": "-- Case 2: III <= 75, currently not 'Resolved' -> should succeed
UPDATE enforcementactions SET resstat = 'Resolved'
WHERE enforcereg = (SELECT ea.enforcereg FROM enforcementactions ea JOIN investigationdetails id ON ea.invdetref = id.invdetreg WHERE ea.resstat <> 'Resolved' AND 0.6*id.behansc + 0.4*id.netansc <= 75.0 LIMIT 1);
SELECT changes() AS rows_updated;"}

{"sql": "CREATE TRIGGER IF NOT EXISTS prevent_premature_resolution_trigger
BEFORE UPDATE OF resstat ON enforcementactions
WHEN NEW.resstat = 'Resolved'
 AND OLD.resstat IS NOT 'Resolved'
 AND (SELECT (0.6 * id.behansc + 0.4 * id.netansc)
      FROM investigationdetails id
      JOIN compliancecase cc ON id.compref = cc.compreg
      WHERE id.invdetreg = NEW.invdetref) > 75.0
BEGIN
  SELECT RAISE(ABORT, 'Premature Resolution Block: Investigation Intensity Index exceeds 75.0; this high-risk enforcement action requires further review before resolution.');
END;

-- Low-risk row (III <= 75): update to Resolved should pass
UPDATE enforcementactions SET resstat = 'Resolved'
WHERE enforcereg = (SELECT ea.enforcereg FROM enforcementactions ea JOIN investigationdetails id ON ea.invdetref = id.invdetreg WHERE ea.resstat <> 'Resolved' AND 0.6*id.behansc + 0.4*id.netansc <= 75.0 LIMIT 1);
SELECT changes() AS low_risk_updated;

-- High-risk row but NOT changing to Resolved (e.g. In Progress -> Pending): should pass
UPDATE enforcementactions SET resstat = 'Pending' WHERE enforcereg = 'ENF_R2LMP';
SELECT changes() AS non_resolution_updated;"}

