{"sql": "CREATE TABLE IF NOT EXISTS container_tss_monitoring (
  containregistry TEXT PRIMARY KEY,
  latest_tss REAL,
  last_updated TEXT
);

WITH ranked AS (
  SELECT s.containlink,
         (1 - s.tempdevcount / 100.0) * (1 - s.critevents / 10.0) * s.tempstabidx AS tss,
         ROW_NUMBER() OVER (PARTITION BY s.containlink ORDER BY s.alerttime DESC, s.sensortrack DESC) AS rn
  FROM sensordata s
)
INSERT INTO container_tss_monitoring (containregistry, latest_tss, last_updated)
SELECT containlink, tss, CURRENT_TIMESTAMP
FROM ranked
WHERE rn = 1
ON CONFLICT(containregistry) DO UPDATE SET
  latest_tss = excluded.latest_tss,
  last_updated = excluded.last_updated;

SELECT COUNT(*) AS rows_in_table FROM container_tss_monitoring;
SELECT * FROM container_tss_monitoring ORDER BY containregistry LIMIT 5;"}

